    [P('killian_bath', 'center', "standing in profile facing frame-left in the corridor, his right fist drawn back an inch from the dark-wood paneled wall, his wet shirt clinging to him", 'obj:the paneled wall in front of him', 'his teeth bared, his brows crashing together')],
