    [P('hunter_chief', 'left', "lying prone on the grass in profile facing frame-right, a long silver sniper rifle propped on a dark rock, the red lens of his mechanical eye pressed against the scope", 'obj:the lit mansion across the valley', 'his jaw tight, his lips pressed flat', eyes='cold grey')],
